from capy_application_acceptor.errors import AcceptorError
try:
    with zipfile.ZipFile(io.BytesIO(payload)) as _z:
        try:
            _info = _z.getinfo('RELEASE-CANDIDATE.json')
        except KeyError:
            _info = None
        print('_info initial', _info is not None)
