            if _info.compress_type != zipfile.ZIP_STORED:
                _info = None
                print('nulled compress')
            elif _info.file_size == 0 or _info.file_size > MANIFEST_MAX_BYTES:
                _info = None
                print('nulled size')
            elif _info.compress_size > OUTER_MAX_BYTES:
                _info = None
                print('nulled csize')
        print('_info after', _info is not None)
        if _info is not None:
            try:
                _raw = _z.read('RELEASE-CANDIDATE.json')
                print('read len',len(_raw))
                if len(_raw) > MANIFEST_MAX_BYTES:
                    _raw = None
                    print('nulled raw len')
